contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint amount, uint unlockTime) public payable {
        require(address(this).balance >= amount);

        // Setup: drive c through its public entry Put to create a nonzero balance for msg.sender
        c.Put{value: amount}(unlockTime);

        // Read the sender's holder balance/meta through the public auto-generated mapping getter
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));

        // Deciding call: call Put again, same sender, same amount; it must not revert per the general rule
        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));

        assert(!reverted);
        assert(afterBalance == beforeBalance + amount);
    }

    receive() external payable {}
}

