contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance");

        c.Put{value: putAmount}(unlockTime);

        (uint beforeBalance,) = c.Acc( address(this) );
        uint beforeContractEther = address(c).balance;

        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        (uint afterBalance,) = c.Acc( address(this) );

        // General rule: Collect completes iff the caller has enough locked balance,
        // the amount is at least MinSum, and the time lock has expired. If it fails,
        // no state or Ether moves.
        assert(
            collectReverted == !(
                beforeBalance >= c.MinSum() &&
                beforeBalance >= collectAmount &&
                block.timestamp > unlockTime
            )
        );
    }

    receive() external payable {}
}

